def nearest_ids(uv,depth,valid,w):
 ids=np.flatnonzero(valid);pixel=np.floor(uv[ids]).astype(np.int64);key=pixel[:,1]*w+pixel[:,0];order=np.lexsort((ids,depth[ids],key));ids=ids[order];key=key[order];return ids[np.r_[True,key[1:]!=key[:-1]]]
def exact_source_coordinates(raw,platform):
 xyz=raw[:,:3].copy()
 if platform=='drone':xyz[:,2]+=1.8 # Exact oldR5float32 in-place operation.
 elif platform!='quad':raise ValueError('Targetaudit isDrone/Quadonly')
 return xyz.astype(np.float32)
