 (R/'GPU_MANIFEST_RECEIPT.json').write_text(json.dumps({'state':'strict9namedkeys_noGTclass_box_map_or_objectindex','keys':keys,'expected_full_n':5912,'expected_smoke_n':20,'files':gpu,'input_plan_sha256':sha(R/'INPUT_PLAN.json'),'private_full_inputs_sha256':sha(EX/'full_inputs.json'),'firstnoun_regex_audit_sha256':sha(R/'FIRST_NOUN_REGEX_AUDIT.json'),'sampling':'ExactoldR5: default_rng(seed).choice(rawN,16384,replace=rawN<16384); raw float32xyz.copy(); Droneinplacez+=1.8,Quadidentity; noGT selection','caption':'Manifestcaption has no artificialsentinel; runneradds exactlyone original . not mentioned suffix','camera_helper_sha256':sha(P/'round7/camera_projection.py'),'missing_distortion_policy':'assume_zero_declared'},indent=2))
 dest=R/'projection_private';dest.mkdir(exist_ok=False);reports=[]
